INTERLIS 2.3; CONTRACTED MODEL F AT "https://example.org" VERSION "1" =
TOPIC T = CLASS A = flag: BOOLEAN; END A; CLASS B = END B; CLASS Other = END Other; CLASS Owner = END Owner;
FUNCTION one(v: OBJECT OF A): BOOLEAN; FUNCTION many(v: OBJECTS OF A): BOOLEAN; FUNCTION manyB(v: OBJECTS OF B): BOOLEAN;
ASSOCIATION Link = a -- {1} A; owner -- {1} Owner;  END Link;
ASSOCIATION Chain = sender -- {1} A; b -- {1} B; END Chain;
CONSTRAINTS OF Owner = MANDATORY CONSTRAINT many(owner[Link]->a); END; END T; END F.

